[Form]
public class GUPPriceDiscPricingRulePreview extends FormRun
{
    private GUPPricingRuleCopy pricingRuleCopy;
    private GUPPricingRuleCopy pricingRuleCopyCustHeader;
    private boolean        previewBothHeaderAndLine = false;
    private boolean        showHeaderPreview = false;
    private boolean        showLinePreview = false;
    private boolean        addProductvariants = false;

    private Query productPreviewQuery;
    private Query custPreviewQuery;
    private Query productVariantPreviewQuery;

}

/// <summary>
/// Initialize form state and variables
/// </summary>
public void init()
{
    if (!element.args().record() || !(element.args().record() is GUPPricingRulePreviewTrans))
    {
        throw Error(Error::wrongUseOfFunction(funcName()));
    }

    GUPPricingRulePreviewTrans pricingRulePreviewTrans = element.args().record() as GUPPricingRulePreviewTrans;
    GUPPriceComponentCodePriceAttributeGroupCombination combination = GUPPriceComponentCodePriceAttributeGroupCombination::find(pricingRulePreviewTrans.PriceComponentCombination);

    GUPRefRecId pricingRuleHeader;

    if (element.args().dataset() == tableNum(RetailPeriodicDiscountLine) ||
        element.args().dataset() == tableNum(RetailDiscountLineThresholdApplying))
    {
        RetailPeriodicDiscountLine retailPeriodicDiscountLine = element.args().record();
        if (element.args().dataset() == tableNum(RetailPeriodicDiscountLine))
        {
            pricingRuleHeader  = element.getGUPPricingRuleHeader(retailPeriodicDiscountLine);
        }
        else
        {
            pricingRuleHeader = RetailPeriodicDiscount::findByOfferId(retailPeriodicDiscountLine.OfferId).HeaderPricingRule;
        }
    }
    else
    {
        pricingRuleHeader = pricingRulePreviewTrans.PricingRuleHeader;
    }

    switch (element.args().menuItemName())
    {
        case menuItemDisplayStr(GUPPriceDiscPricingRulePreview):
            pricingRuleCopyCustHeader = GUPPricingRuleCopy::findByRuleId(pricingRuleHeader);
            showHeaderPreview = (combination.HeaderGroupAll == GUPGroupAll::Group);
            break;

        case menuItemDisplayStr(GUPPriceDiscPricingRulePreviewLine):
            pricingRuleCopy = GUPPricingRuleCopy::findByRuleId(pricingRulePreviewTrans.PricingRuleLine);
            showLinePreview = (combination.LineGroupAll == GUPGroupAll::Group);
            break;

        case menuItemDisplayStr(GUPPriceDiscPricingRulePreviewAll):
            pricingRuleCopyCustHeader.initFromPricingRule(GUPPricingRule::find(pricingRuleHeader));
            pricingRuleCopy.initFromPricingRule(GUPPricingRule::find(pricingRulePreviewTrans.PricingRuleLine));
            previewBothHeaderAndLine = true;
            showHeaderPreview = (combination.HeaderGroupAll == GUPGroupAll::Group);
            showLinePreview = (combination.LineGroupAll == GUPGroupAll::Group);
            break;

        default: throw Error(Error::wrongUseOfFunction(funcName()));
    }

    element.initFormPricingObjectPreviewQuery();

    super();

    element.setControlsVisible();
}

protected RefRecId getGUPPricingRuleHeader(RetailPeriodicDiscountLine _retailPeriodicDiscountLine)
{
    return RetailPeriodicDiscount::findByOfferId(_retailPeriodicDiscountLine.OfferId).HeaderPricingRule;
}

private void togglePricingRuleIncludeExcludeButtonVisibility(boolean _showExclude, GUPPricingAttributeSourceLevel sourceLevel)
{
    switch (sourceLevel)
    {
        case GUPPricingAttributeSourceLevel::Header:
            ExcludeCustBtn.visible(_showExclude);
            IncludeCustBtn.visible(!_showExclude);
            break;
        case GUPPricingAttributeSourceLevel::Line:
            ExcludeItemBtn.visible(_showExclude);
            IncludeItemBtn.visible(!_showExclude);
            ExcludeProductVariantBtn.visible(_showExclude);
            IncludeProductVariantBtn.visible(!_showExclude);
            break;
    }
}

private void toggleInventTableProductVariantPreviewVisibility(boolean _addProductVariants = false)
{
    GUPPricingAttributeGroup attributeGroup;
    select firstonly attributeGroup where attributeGroup.Name == pricingRuleCopy.PriceAttributeGroupName;

    if (attributeGroup.RecId &&
        attributeGroup.matchSource(GUPPricingAttributeSource::Product))
    {
        PreviewProductTabPage.enabled(!_addProductVariants);
        PreviewProductTabPage.visible(!_addProductVariants);
        PreviewProductVariantTabPage.enabled(_addProductVariants);
        PreviewProductVariantTabPage.visible(_addProductVariants);

        if (_addProductVariants)
        {
            Query inventTableQuery = new Query();
            inventTableQuery.addDataSource(tableNum(InventTable))
                .addRange(fieldNum(InventTable, RecId))
                .value(int2Str(-1));

            element.productPreviewQuery = inventTableQuery;
            element.productVariantPreviewQuery = GUPPricingObjectQueryBuilder::constructFromPricingRuleCopy(pricingRuleCopy)
                    .addProductVariants()
                    .build();
            EcoResDistinctProductVariant_ds.executeQuery();
            PreviewProductVariantTabPage.fastTabExpanded(FastTabExpanded::Yes);
        }
        else
        {
            Query productVariantQuery = new Query();
            productVariantQuery.addDataSource(tableNum(EcoResDistinctProductVariant))
                .addRange(fieldNum(EcoResDistinctProductVariant, RecId))
                .value(int2Str(-1));

            element.productVariantPreviewQuery = productVariantQuery;
            element.productPreviewQuery = GUPPricingObjectQueryBuilder::constructFromPricingRuleCopy(pricingRuleCopy)
                    .build();
            InventTable_ds.executeQuery();
        }
    }
}

/// <summary>
/// Set controls visible depending on source level
/// </summary>
public void setControlsVisible()
{
    element.addProductvariants = pricingRuleCopy.ExclusionType == GUPPricingRuleExclusionType::ProductVariant;

    if (showHeaderPreview)
    {
        element.initCustTablePreview();
        PreviewCustTabPage.visible(true);
    }
    if (showLinePreview)
    {
        element.initInventTablePreview();
    }

    // View only
    if (previewBothHeaderAndLine)
    {
        PreviewCustTabPage.visible(true);
        PreviewCustTabPage.expand();
        PreviewProductTabPage.visible(pricingRuleCopy.ExclusionType == GUPPricingRuleExclusionType::Product);
        PreviewProductVariantTabPage.visible(pricingRuleCopy.ExclusionType == GUPPricingRuleExclusionType::ProductVariant);
        PreviewProductTabPage.expand();
        PreviewProductVariantTabPage.expand();
        PreviewCustActionPanel.visible(false);
        PreviewProductActionPanel.visible(false);
        PreviewProductVariantActionPanel.visible(false);
        if (!showHeaderPreview)
        {
            PreviewCustTabPage.visible(false);
        }

        if (!showLinePreview)
        {
            PreviewProductTabPage.visible(false);
            PreviewProductVariantTabPage.visible(false);
        }
    }
    else
    {
        PreviewCustTabPage.visible(showHeaderPreview);
        PreviewCustTabPage.expand();
        PreviewProductTabPage.visible(showLinePreview && !addProductvariants);
        PreviewProductVariantTabPage.visible(showLinePreview && addProductvariants);
        PreviewProductTabPage.expand();
        PreviewProductVariantTabPage.expand();
    }
}

private void initFormPricingObjectPreviewQuery()
{
    Query inventTableQuery, custTableQuery, productVariantQuery;

    custTableQuery = new Query();
    custTableQuery.addDataSource(tableNum(CustTable))
        .addRange(fieldNum(CustTable, RecId))
        .value(int2Str(-1));

    inventTableQuery = new Query();
    inventTableQuery.addDataSource(tableNum(InventTable))
        .addRange(fieldNum(InventTable, RecId))
        .value(int2Str(-1));

    productVariantQuery = new Query();
    productVariantQuery.addDataSource(tableNum(EcoResDistinctProductVariant))
        .addRange(fieldNum(EcoResDistinctProductVariant, RecId))
        .value(int2Str(-1));

    element.custPreviewQuery = custTableQuery;
    element.productPreviewQuery = inventTableQuery;
    element.productVariantPreviewQuery = productVariantQuery;
}

private void initCustTablePreview()
{
    if (pricingRuleCopyCustHeader.PriceAttributeGroupName != '')
    {
        element.custPreviewQuery = GUPPricingObjectQueryBuilder::constructFromPricingRuleCopy(pricingRuleCopyCustHeader).build();
        CustTable_ds.executeQuery();
    }
    else
    {
        PreviewCustTabPage.visible(false);
    }
}

private void initInventTablePreview()
{
    element.addProductvariants = (pricingRuleCopy.ExclusionType == GUPPricingRuleExclusionType::ProductVariant);

    if (pricingRuleCopy.PriceAttributeGroupName != '')
    {
        if (!element.addProductvariants)
        {
            element.productPreviewQuery = GUPPricingObjectQueryBuilder::constructFromPricingRuleCopy(pricingRuleCopy).build();
            InventTable_ds.executeQuery();
            PreviewProductVariantTabPage.visible(false);
        }
        else
        {
            element.productVariantPreviewQuery = GUPPricingObjectQueryBuilder::constructFromPricingRuleCopy(pricingRuleCopy).addProductVariants().build();
            EcoResDistinctProductVariant_ds.executeQuery();
            PreviewProductTabPage.visible(false);
        }
    }
    else
    {
        PreviewProductVariantTabPage.visible(false);
        PreviewProductTabPage.visible(false);
    }
}

/// <summary>
/// Execute query for customer data source
/// </summary>
public void executeQuery()
{
    this.query(custPreviewQuery);
    super();
}

public display str displayCustTableExclusion(CustTable _custTable)
{
    GUPPricingRuleExclusionCopy excluded;
    select firstonly RecId from excluded where excluded.Exclusion == _custTable.AccountNum && excluded.RuleId == pricingRuleCopyCustHeader.RuleId;

    if (excluded.RecId)
    {
        return "@GlobalUnifiedPricing:GUPAddPriceAttributeGroup_Exclude";
    }
    else
    {
        return "@GlobalUnifiedPricing:GUPAddPriceAttributeGroup_Include";
    }
}

public void markChanged()
{
    super();

    MultiSelectionHelper selectionHelper = MultiSelectionHelper::construct();
    CustTable custTableExclusion;
    selectionHelper.parmDatasource(CustTable_ds);
    custTableExclusion = selectionHelper.getFirst();

    while (custTableExclusion)
    {
        if (pricingRuleCopyCustHeader.isExcluded(custTableExclusion.AccountNum))
        {
            element.togglePricingRuleIncludeExcludeButtonVisibility(false, GUPPricingAttributeSourceLevel::Header);
            return;
        }
        custTableExclusion = selectionHelper.getNext();
    }

    element.togglePricingRuleIncludeExcludeButtonVisibility(true, GUPPricingAttributeSourceLevel::Header);
}

/// <summary>
/// Execute query for product data source
/// </summary>
public void executeQuery()
{
    this.query(element.productPreviewQuery);

    super();
}

