/// <summary>
/// Expand product variants
/// </summary>
public void clicked()
{
    super();
    Query previewQuery =
        GUPPricingObjectQueryBuilder::constructFromPricingRuleCopy(pricingRuleCopy)
            .addProductVariants()
            .build();
    QueryRun qr = new QueryRun(previewQuery);
    qr.next();
    Common first = qr.getNo(1);

    if (first.RecId)
    {
        ttsbegin;

        pricingRuleCopy.selectForUpdate(true);
        pricingRuleCopy.clearRuleExclusions();
        pricingRuleCopy.ExclusionType = GUPPricingRuleExclusionType::ProductVariant;
        pricingRuleCopy.write();
        ttscommit;

        element.toggleInventTableProductVariantPreviewVisibility(true);
    }
    else
    {
        warning("@GlobalUnifiedPricing:GUPAddPriceAttributeGroup_AllVariants_NoVariant");
    }
}

